<?php
namespace App\Filament\Widgets;
use App\Models\Business; use App\Models\User; use Filament\Widgets\StatsOverviewWidget; use Filament\Widgets\StatsOverviewWidget\Stat; use Illuminate\Support\Facades\DB;
class AdminStatsOverview extends StatsOverviewWidget { protected function getStats(): array { return [Stat::make(__('filament.widgets.daily_active_users'), DB::table('personal_access_tokens')->where('last_used_at','>=',now()->subDay())->distinct('tokenable_id')->count('tokenable_id'))->description(__('filament.widgets.unique_users_active_24_hours')), Stat::make(__('filament.widgets.monthly_active_users'), DB::table('personal_access_tokens')->where('last_used_at','>=',now()->subDays(30))->distinct('tokenable_id')->count('tokenable_id')), Stat::make(__('filament.widgets.active_businesses'), Business::active()->count()), Stat::make(__('filament.widgets.expiring_within_7_days'), Business::query()->where('status','active')->whereBetween('expires_at',[now(),now()->addDays(7)])->count()), Stat::make(__('filament.widgets.open_moderation_reports'), DB::table('moderation_reports')->where('status','open')->count())]; } }
